1	// src/lib/rechner/parkplatz.js – Parkplatz-Hub (Welle 4): Schnell-Check Solarpflicht & Potenzial
2	//
3	// Reine Logik ohne UI. Drei Fragen, ehrliche Antwort:
4	//  1. Gilt für diesen Parkplatz eine Solarpflicht? → ja / nein / unklar, immer mit Rechtsgrundlage
5	//     und Quelle. Datengrundlage ist die fachlich geprüfte Übersicht aus dem Ratgeber
6	//     src/content/ratgeber/parkplatz-solarpflicht-bundeslaender.js (Landesrecht geprüft 09/2026,
7	//     Primärquellen dort je Land). NUR DACH: Deutschland je Bundesland; Österreich und Schweiz
8	//     ohne erfundene Regeln → Status „unklar“ mit ehrlichem Text (kein flächendeckendes
9	//     Parkplatz-Gesetz bekannt; Länder bzw. Kantone regeln unterschiedlich).
10	//  2. Potenzial in kWp: Stellplätze × CARPORT.kwpProStellplatz (belegte Flächenannahme
11	//     2,5 × 5 m je Stellplatz, Module ≈ 225 Wp/m² – src/lib/invest/markt.js, Stand dort).
12	//  3. Ladepunkte nach GEIG (nur DE): §§ 7, 8, 10 GEIG – Leitungsinfrastruktur und
13	//     Mindest-Ladepunkte je nach Neubau, größerer Renovierung oder Bestand.
14	//
15	// Keine Geldwerte, keine Rechtsberatung: Maßgeblich ist der Gesetzestext zum Zeitpunkt des
16	// Bauantrags; der Check liefert eine erste Orientierung mit Quelle.
17	
18	import { CARPORT } from "../invest/markt.js";
19	
