41	  geig: { titel: "Gebäude-Elektromobilitätsinfrastruktur-Gesetz (GEIG) § 7", url: "https://www.gesetze-im-internet.de/geig/__7.html", stand: "09/2026" },
42	  ratgeber: { titel: "ÖkoInvest-Ratgeber: Solarpflicht für Parkplätze nach Bundesland (eigene Zusammenstellung aus Landesrecht)", url: "/ratgeber/parkplatz-solarpflicht-bundeslaender", stand: "09/2026" },
43	});
