61	  bremen: { name: "Bremen", keine: true, grundlage: "BremSolarG (nur Gebäude)" },
62	  hamburg: { name: "Hamburg", schwelle: 35, art: "mehr", umfang: "40 % der geeigneten Fläche", umfangAnteil: 0.4, seit: "01.01.2024", grundlage: "§ 16a HmbKliSchG, PVUmsVO", erweiterung: "ja", sanierung: "nein", quelle: Q.hh },
63	  hessen: { name: "Hessen", schwelle: 50, art: "mehr", umfang: "Anlage über der Stellplatzfläche", seit: "Bauantrag nach 29.11.2023", grundlage: "Hessisches Energiegesetz (HEG)", hinweis: "Landeseigene Parkplätze schon ab mehr als 35 Stellplätzen.", erweiterung: "unklar", sanierung: "nein" },
64	  "mecklenburg-vorpommern": { name: "Mecklenburg-Vorpommern", keine: true, grundlage: "keine Parkplatzpflicht" },
65	  niedersachsen: { name: "Niedersachsen", schwelle: 25, art: "mehr", umfang: "Solaranlage über der Stellplatzfläche", seit: "01.01.2025 (vorher mehr als 50)", grundlage: "§ 32a Abs. 3 NBauO", erweiterung: "ja", sanierung: "ja", sanierungText: "auch bei Erneuerung von mindestens 50 % eines bestehenden Parkplatzes", quelle: Q.ni },
66	  "nordrhein-westfalen": { name: "Nordrhein-Westfalen", schwelle: 35, art: "mehr", umfang: "30 % der geeigneten Fläche, alternativ ein Laubbaum je 5 Stellplätze", umfangAnteil: 0.3, seit: "01.01.2022", grundlage: "§ 48 Abs. 1a BauO NRW, SAN-VO NRW", hinweis: "Gilt für notwendige Stellplätze eines Nichtwohngebäudes.", erweiterung: "unklar", sanierung: "nein", quelle: Q.nrw },
67	  "rheinland-pfalz": { name: "Rheinland-Pfalz", schwelle: 50, art: "ab", umfang: "60 % der geeigneten Fläche", umfangAnteil: 0.6, seit: "01.01.2023 (öffentlich 2024)", grundlage: "Landessolargesetz (LSolarG)", hinweis: "Gilt für gewerblich und öffentlich genutzte Parkplätze.", erweiterung: "unklar", sanierung: "nein" },
68	  saarland: { name: "Saarland", schwelle: 35, art: "ab", umfang: "60 % der geeigneten Fläche", umfangAnteil: 0.6, seit: "2025", grundlage: "§§ 12a, 12b LBO Saarland", oeffentlichOhneSchwelle: true, hinweis: "Öffentliche Parkplätze sind unabhängig von der Schwelle erfasst.", erweiterung: "unklar", sanierung: "nein" },
69	  sachsen: { name: "Sachsen", keine: true, grundlage: "keine Parkplatzpflicht" },
70	  "sachsen-anhalt": { name: "Sachsen-Anhalt", keine: true, grundlage: "keine Parkplatzpflicht" },
71	  "schleswig-holstein": { name: "Schleswig-Holstein", schwelle: 70, art: "mehr", umfang: "Neubau und grundlegende Sanierung", seit: "Novelle 2025, Übergangsjahr", grundlage: "§ 25 EWKG", erweiterung: "unklar", sanierung: "ja", sanierungText: "auch bei grundlegender Sanierung", quelle: Q.sh },
72	  thueringen: { name: "Thüringen", keine: true, grundlage: "keine Parkplatzpflicht" },
