74	
75	export const BUNDESLAND_SLUGS = Object.freeze(Object.keys(PFLICHT_REGELN));
76	
77	/** Bundesweit ab 2030: § 106 GModG – neue überdachte Parkplätze, die an ein Gebäude angrenzen */
78	export const GMODG_2030 = Object.freeze({
79	  text: "Bundesweit ab 01.01.2030: Auf neuen überdachten Parkplätzen, die physisch an ein Gebäude angrenzen, sind Solaranlagen Pflicht (§ 106 GModG, Umsetzung der EU-Gebäuderichtlinie). Offene Parkplätze erfasst die Bundesregel nicht; strengere Landesregeln bleiben zulässig.",
80	  quelle: Q.gmodg,
81	});
