83	/* ------------------------------------------------------------------ */
84	/* Pflicht-Prüfung                                                     */
85	/* ------------------------------------------------------------------ */
86	
87	const GRENZEN = Object.freeze({ stellplaetzeMin: 1, stellplaetzeMax: 20000 });
88	export { GRENZEN as GRENZEN_PARKPLATZ };
89	
90	/**
91	 * Schnell-Check: Gilt eine Solarpflicht?
92	 * @param {{ land: "DE"|"AT"|"CH", region?: string, stellplaetze: number, situation?: string, betreiber?: string }} e
93	 * @returns {{ status: "ja"|"nein"|"unklar", code: string, regel: object|null, quelle: object|null }}
94	 */
95	export function pruefePflicht({ land = "DE", region = "", stellplaetze = 0, situation = "neubau", betreiber = "gewerblich" } = {}) {
96	  if (land === "AT") return { status: "unklar", code: "at", regel: null, quelle: null };
97	  if (land === "CH") return { status: "unklar", code: "ch", regel: null, quelle: null };
98	  const r = PFLICHT_REGELN[region];
99	  if (!r) return { status: "unklar", code: "region-fehlt", regel: null, quelle: null };
100	  const regel = { slug: region, ...r, quelle: r.quelle || Q.ratgeber };
101	  const quelle = regel.quelle;
102	  if (r.keine) return { status: "nein", code: r.aufgehoben ? "aufgehoben" : "keine-pflicht", regel, quelle };
103	
104	  const erreicht = (r.art === "ab" ? stellplaetze >= r.schwelle : stellplaetze > r.schwelle) || (r.oeffentlichOhneSchwelle && betreiber === "oeffentlich");
105	  if (situation === "bestand") return { status: "nein", code: "bestand", regel, quelle };
106	  if (situation === "sanierung") {
107	    if (r.sanierung !== "ja") return { status: "nein", code: "sanierung-keine", regel, quelle };
108	    return erreicht ? { status: "ja", code: "sanierung", regel, quelle } : { status: "nein", code: "unter-schwelle", regel, quelle };
109	  }
110	  if (!erreicht) return { status: "nein", code: "unter-schwelle", regel, quelle };
111	  if (situation === "erweiterung" && r.erweiterung !== "ja") return { status: "unklar", code: "erweiterung-unklar", regel, quelle };
112	  return { status: "ja", code: situation === "erweiterung" ? "erweiterung" : "ueber-schwelle", regel, quelle };
113	}
114	
115	/* ------------------------------------------------------------------ */
116	/* Potenzial & GEIG                                                    */
117	/* ------------------------------------------------------------------ */
118	
119	/**
120	 * PV-Potenzial des Parkplatzes bei vollständiger Überdachung.
121	 * Flächenannahme: CARPORT.kwpProStellplatz (2,5 × 5 m je Stellplatz, Module ≈ 225 Wp/m²).
122	 * mindestKwp nur als grobe Orientierung, wo das Land einen Flächenanteil nennt –
123	 * maßgeblich ist die geeignete Fläche, nicht die Leistung.
124	 */
125	export function potenzial({ stellplaetze = 0, umfangAnteil = null } = {}) {
126	  const st = Math.max(0, stellplaetze);
127	  const kwp = Math.round(st * CARPORT.kwpProStellplatz);
128	  return {
129	    kwp,
130	    kwpProStellplatz: CARPORT.kwpProStellplatz,
131	    mindestKwp: umfangAnteil ? Math.round(kwp * umfangAnteil) : null,
132	    flaecheM2: Math.round(st * CARPORT.stellplatzM2),
133	  };
134	}
135	
136	/**
137	 * Ladepunkte nach GEIG (nur Deutschland, Nichtwohngebäude):
138	 *  - Neubau mit mehr als 6 Stellplätzen: Leitungsinfrastruktur für jeden 3. Stellplatz, mindestens 1 Ladepunkt (§ 7 GEIG).
139	 *  - Größere Renovierung mit mehr als 10 Stellplätzen: jeder 5. Stellplatz, mindestens 1 Ladepunkt (§ 8 GEIG).
140	 *  - Bestand mit mehr als 20 Stellplätzen: seit 01.01.2025 mindestens 1 Ladepunkt (§ 10 GEIG).
141	 * @returns {{ greift: boolean, paragraph: string|null, leitungJe: number|null, leitungStellplaetze: number, ladepunkteMin: number }|null}
142	 */
143	export function geigCheck({ land = "DE", stellplaetze = 0, situation = "neubau" } = {}) {
144	  if (land !== "DE") return null;
145	  const st = Math.max(0, Math.floor(stellplaetze));
146	  if ((situation === "neubau" || situation === "erweiterung") && st > 6) {
147	    return { greift: true, paragraph: "§ 7 GEIG", leitungJe: 3, leitungStellplaetze: Math.ceil(st / 3), ladepunkteMin: 1 };
148	  }
149	  if (situation === "sanierung" && st > 10) {
150	    return { greift: true, paragraph: "§ 8 GEIG", leitungJe: 5, leitungStellplaetze: Math.ceil(st / 5), ladepunkteMin: 1 };
151	  }
152	  if (situation === "bestand" && st > 20) {
153	    return { greift: true, paragraph: "§ 10 GEIG", leitungJe: null, leitungStellplaetze: 0, ladepunkteMin: 1 };
154	  }
155	  return { greift: false, paragraph: null, leitungJe: null, leitungStellplaetze: 0, ladepunkteMin: 0 };
156	}
157	
158	/** Gesamtergebnis des Schnell-Checks (Pflicht + Potenzial + GEIG) */
159	export function parkplatzCheck(e = {}) {
160	  const pflicht = pruefePflicht(e);
161	  return {
162	    version: PARKPLATZ_VERSION,
163	    stand: PFLICHT_STAND,
164	    pflicht,
165	    potenzial: potenzial({ stellplaetze: e.stellplaetze, umfangAnteil: pflicht.status === "ja" ? pflicht.regel?.umfangAnteil || null : null }),
166	    geig: geigCheck(e),
167	    gmodg2030: e.land === "DE" || !e.land ? GMODG_2030 : null,
168	  };
169	}
